def _hit(text_lower, rule):
    if rule.startswith("re:"):
        try:
            return re.search(rule[3:], text_lower) is not None
        except re.error:
            return False
    return rule.lower() in text_lower


def find_help(error_text, patterns=None):
    """The patterns matching ``error_text`` (at most MAX_MATCHES), in order."""
    text = (error_text or "").lower()
    found = []
    for p in (patterns if patterns is not None else DEFAULT_PATTERNS):
        if not isinstance(p, dict) or not p.get("tip"):
            continue
        rules = p.get("match") or []
        if isinstance(rules, str):
            rules = [rules]
        if any(_hit(text, str(r)) for r in rules):
            found.append(p)
            if len(found) >= MAX_MATCHES:
                break
    return found


def help_text(matches):
    """One display text for the matches ('' when none)."""
    return "\n\n".join(f"{m.get('title') or ''}\n{m['tip']}".strip() for m in matches)
